import XCTest

final class TapTests: XCTestCase {
    func testOpenTeamStandup() {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        if app.state == .notRunning { app.launch() } else { app.activate() }
        let openButton = app.alerts.buttons["Open"]
        if openButton.waitForExistence(timeout: 5) { openButton.tap() }
        let team = app.staticTexts["Team Standup"]
        XCTAssertTrue(team.waitForExistence(timeout: 10), "Team Standup should be visible in the chat list")
        team.tap()
        XCTAssertTrue(app.navigationBars["Team Standup"].waitForExistence(timeout: 10) || app.staticTexts["Team Standup"].exists)
    }
}
EOF

